class Solution {
    public int countBinarySubstrings(String s){
        int previous=0,current=1,answer=0;
        for(int i=1;i<s.length();i++)if(s.charAt(i)==s.charAt(i-1))current++;
        else{
            answer+=Math.min(previous,current);
            previous=current;
            current=1;
        }
        return answer+Math.min(previous,current);
    }
}

code.kotlin:
class Solution {
    fun countBinarySubstrings(s:String):Int{
        var previous=0;
        var current=1;
        var answer=0;
        for(i in 1 until s.length)if(s[i]==s[i-1])current++ else{
            answer+=minOf(previous,current);
            previous=current;
            current=1
        };
        return answer+minOf(previous,current)
    }
}

code.cpp:
class Solution {
    public: int countBinarySubstrings(string s){
        int previous=0,current=1,answer=0;
        for(int i=1;i<(int)s.size();++i)if(s[i]==s[i-1])++current;
        else{
            answer+=min(previous,current);
            previous=current;
            current=1;
        }
        return answer+min(previous,current);
    }
};
